package app.netlog;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
public final class ReportExporter { public void csv(Path p,List<Packet> ps)throws IOException{try(PrintWriter w=new PrintWriter(Files.newBufferedWriter(p,StandardCharsets.UTF_8))){w.println("timestamp,source,destination,protocol,bytes");for(Packet x:ps)w.println(q(x.timestamp.toString())+","+q(x.source)+","+q(x.destination)+","+q(x.protocol)+","+x.bytes);}} public void text(Path p,Analyzer.Summary s)throws IOException{try(PrintWriter w=new PrintWriter(Files.newBufferedWriter(p,StandardCharsets.UTF_8))){w.println("Network log analysis");w.println("Packets: "+s.totalPackets);w.println("Bytes: "+s.totalBytes);w.println("By protocol: "+s.byProtocol);w.println("By source: "+s.bySource);w.println("Alerts: "+s.alerts);}}private String q(String s){return "\""+s.replace("\"","\"\"")+"\"";}}
